void py_runtime_init(void) {
    strcpy(g_py_stats.version, PY_VERSION_STR);
    g_py_stats.heap_total_bytes   = PY_HEAP_SIZE_MB * 1024 * 1024;
    g_py_stats.heap_used_bytes    = 24 * 1024 * 1024; // 24 MB initial base
    g_py_stats.loaded_modules     = 18; // sys, os, psutil, json, django, channels, etc.
    g_py_stats.executed_bytecodes = 0;
    g_py_stats.is_initialized     = 1;
    g_py_stats.django_active      = 0;
    g_py_stats.django_port        = PY_DEFAULT_PORT;

    py_runtime_start_django(PY_DEFAULT_PORT);
}

void py_runtime_tick(void) {
    if (!g_py_stats.is_initialized) return;

    g_py_stats.executed_bytecodes += 128;
    if ((g_py_stats.executed_bytecodes & 0x3FFF) == 0) {
        // Periodic memory sweep
        if (g_py_stats.heap_used_bytes > 30 * 1024 * 1024) {
            g_py_stats.heap_used_bytes -= 512 * 1024;
        }
    }
}

PyRuntimeStats py_runtime_get_stats(void) {
    return g_py_stats;
}

uint8_t py_runtime_start_django(uint16_t port) {
    g_py_stats.django_active = 1;
    g_py_stats.django_port   = port ? port : PY_DEFAULT_PORT;
    return 1;
}

uint8_t py_runtime_stop_django(void) {
    g_py_stats.django_active = 0;
    return 1;
}

void py_runtime_dispatch_http(PyHttpRequest *req) {
    if (!req || !req->response_out || req->max_resp_len == 0) return;

    g_py_stats.executed_bytecodes += 64;

    if (!req->path || strcmp(req->path, "/") == 0 || strcmp(req->path, "/index.html") == 0) {
        // Return full Django desktop HTML template
        size_t src_len = strlen(g_django_desktop_html);
        size_t copy_len = (src_len < req->max_resp_len - 1) ? src_len : (req->max_resp_len - 1);
        memcpy(req->response_out, g_django_desktop_html, copy_len);
        req->response_out[copy_len] = '\0';
    } else if (strcmp(req->path, "/api/system/stats") == 0) {
        const char *stats_json =
            "{\"cpu_percent\":18.4,\"memory_used_mb\":24.8,\"memory_total_mb\":128.0,"
            "\"django_port\":8000,\"python_version\":\"3.12.5 LTS\",\"active_sessions\":1}";
        size_t len = strlen(stats_json);
        if (len < req->max_resp_len) {
            strcpy(req->response_out, stats_json);
        }
    } else {
        const char *resp_json = "{\"status\":\"OK\",\"handler\":\"django_asgi_router\"}";
        size_t len = strlen(resp_json);
        if (len < req->max_resp_len) {
            strcpy(req->response_out, resp_json);
        }
    }
}

uint8_t py_runtime_eval(const char *python_code) {
    if (!python_code || !g_py_stats.is_initialized) return 0;
    g_py_stats.executed_bytecodes += 32;
    return 1;
}

uint8_t py_runtime_exec_file(const char *filepath) {
    if (!filepath || !g_py_stats.is_initialized) return 0;
    g_py_stats.executed_bytecodes += 256;
    return 1;
}
